package com.insight.quantlife.tests;
import android.app.*;import android.os.*;import android.database.sqlite.SQLiteDatabase;import org.json.*;import com.insight.quantlife.*;
/** Synthetic records with production DB labeling and real WebView interactions. */
public final class QuantDashboardTest extends DocumentEditorTest {
 String prefix="quant-ui-";
 JSONObject seed(String suffix,String type,int minutes,String note)throws Exception{JSONObject r=new JSONObject().put("id",prefix+suffix).put("type",type).put("date","2000-02-29").put("title","合成记录 "+suffix).put("note",note).put("durationMinutes",minutes).put("tags",new JSONArray());if(type.equals("idea"))r.put("occurredAt","2000-02-29T10:00:00");h.call("saveRecord",new JSONObject().put("record",r).put("allowDuplicate",true));return record(r.getString("id"));}
 JSONObject evidence(String kind,String quote,String actor,String status)throws Exception{return new JSONObject().put("kind",kind).put("quote",quote).put("actor",actor).put("status",status).put("claim","原文中的行为依据");}
 void label(JSONObject r,String primary,JSONArray evidence)throws Exception{try(SQLiteDatabase db=SQLiteDatabase.openDatabase(getTargetContext().getDatabasePath("quantlife.db").getPath(),null,SQLiteDatabase.OPEN_READWRITE|SQLiteDatabase.ENABLE_WRITE_AHEAD_LOGGING)){QwenLabels.step(db,r,in->new JSONObject().put("recordId",r.getString("id")).put("primary",primary).put("domains",new JSONArray().put("AI 与技术")).put("topics",new JSONArray().put("检索方法")).put("evidence",evidence));}}
 void clean()throws Exception{for(String id:new String[]{"a","b","c"})h.call("deleteRecord",new JSONObject().put("id",prefix+id));}
 void fits(String text)throws Exception{check(h.js("document.documentElement.scrollWidth<=innerWidth+1&&[...document.querySelectorAll('.quant-card button')].every(x=>{const r=x.getBoundingClientRect();return r.width===0||(r.left>=-1&&r.right<=innerWidth+1&&r.height>=47)})").equals("true"),text+": no overflow and controls remain touchable");check(h.js("[...document.querySelectorAll('.quant-card .domain-row strong')].every(x=>x.scrollWidth<=x.clientWidth+1)").equals("true"),text+": labels remain readable");}
 @Override public void onStart(){Bundle out=new Bundle();boolean success=false;try{
  if(!Build.HARDWARE.matches("ranchu|goldfish"))throw new Exception("Disposable emulator required");h=new MainHost(this);h.open();until("typeof document.querySelector('[data-page=records]').onclick==='function'");h.js("AutoWiki.kick=()=>{};AutoWiki.resume=()=>{}");clean();
  String practice="我修改了统一的重试机制，并在项目中实际应用。",ongoing="正在跑80%目标的回归测试，还没有得到结果。",excerpt="文章介绍了某公司采用新的检索策略，并完成了验证。";
  JSONObject a=seed("a","learning",25,practice+ongoing),b=seed("b","learning",0,excerpt);seed("c","learning",50,"这篇学习记录尚未做任何量化打标，保留待整理。");
  label(a,"improve",new JSONArray().put(evidence("method_change",practice,"self","completed")).put(evidence("application",practice,"self","completed")).put(evidence("verification",ongoing,"self","ongoing")));label(b,"reference",new JSONArray().put(evidence("application",excerpt,"source","completed")));
  String before=records().toString();runOnMainSync(()->h.activity.finish());h=new MainHost(this);h.open();until("typeof document.querySelector('[data-page=records]').onclick==='function'");h.js("AutoWiki.kick=()=>{};AutoWiki.resume=()=>{}");click("[data-page=records]");click("#topic-entry");click("[data-topic-range=custom]");h.js("document.querySelector('#topic-start').value='2000-02-01';document.querySelector('#topic-start').dispatchEvent(new Event('input'));document.querySelector('#topic-end').value='2000-02-29';document.querySelector('#topic-end').dispatchEvent(new Event('input'));document.querySelector('#topic-dates').requestSubmit()");
  check(h.js("!!document.querySelector('.quant-card')&&!document.querySelector('.evidence-duration')&&!document.body.innerText.includes('每条学习时长')").equals("true"),"Redundant duration scatter is fully removed");check(h.js("document.querySelector('.quant-card').innerText.includes('已整理 2/3')").equals("true"),"Coverage separates labeled and pending records");
  check(h.js("document.querySelector('[data-quant-pick=\"facet:practice\"] strong').textContent.includes('1')&&document.querySelector('[data-quant-pick=\"facet:verification\"] strong').textContent.includes('0')").equals("true"),"Personal practice counts once and ongoing target test is not a measured result");
  fits(phase);h.js("document.querySelector('.quant-card').scrollIntoView({block:'start'})");h.screenshot("quant-dashboard-"+phase+".png");
  h.js("document.querySelector('[data-quant-pick=\"facet:practice\"]').scrollIntoView({block:'center'})");h.tap("[data-quant-pick='facet:practice']",false);until("!!document.querySelector('#quant-detail')");check(h.js("document.querySelectorAll('#quant-detail [data-record]').length===1&&document.querySelector('#quant-detail blockquote').textContent.includes('统一的重试机制')").equals("true"),"Actual tap opens only source-grounded personal practice");
  click("#quant-detail [data-record]");until("!!document.querySelector('#doc-mode')");check(h.js("document.querySelector('#doc-flow').textContent.includes('统一的重试机制')").equals("true"),"Evidence drilldown opens original record reader");close();click("[data-quant-pick='facet:verification']");check(h.js("document.querySelector('#quant-detail').textContent.includes('还没有这一类依据')").equals("true"),"Zero verification is stated as no recorded evidence, not failed ability");
  click("[data-quant-pick='primary:reference']");check(h.js("document.querySelector('#quant-detail').textContent.includes('资料内容')&&document.querySelectorAll('#quant-detail [data-record]').length===1").equals("true"),"Third-party activity remains visibly attributed to source material");
  click("#quant-close");runOnMainSync(()->h.web.getSettings().setTextZoom(200));Thread.sleep(350);fits("200% "+phase);h.js("document.querySelector('.quant-card').scrollIntoView({block:'start'})");h.screenshot("quant-large-"+phase+".png");runOnMainSync(()->h.web.getSettings().setTextZoom(100));check(records().toString().equals(before),"Dashboard and source navigation leave all originals untouched");
  JSONObject edited=record(prefix+"a");edited.put("durationMinutes",35);h.call("saveRecord",new JSONObject().put("record",edited).put("allowDuplicate",true));check(!QwenLabels.current(record(prefix+"a")),"A saved edit invalidates the old labeling version");success=true;
 }catch(Throwable error){out.putString("stream","FAIL QuantDashboardTest after "+passed+": "+error+"\n"+android.util.Log.getStackTraceString(error));try{if(h!=null)h.screenshot("quant-ui-failure.png");}catch(Exception ignored){}}
 finally{if(h!=null){try{runOnMainSync(()->h.web.getSettings().setTextZoom(100));clean();}catch(Exception ignored){}}}
 if(success)out.putString("stream","PASS QuantDashboardTest "+phase+": "+passed+" checks\n");finish(success?Activity.RESULT_OK:Activity.RESULT_CANCELED,out);
 }
}
